import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#8
it('reports an undefined hook rejection with its cause and rethrows it unchanged', async () => {
  const failures: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Assistant'}),
    undefined,
    {
      hooks: {
        beforeModelResponse: async () => Promise.reject(undefined),
        onError: async (_session, error) => void failures.push(error),
      },
    }
  );
  const outcome = await orchestrator.processMessage(session).then(
    value => ({resolved: value}),
    (reason: unknown) => ({rejected: reason})
  );

  expect({
    outcome,
    count: failures.length,
    isError: failures[0] instanceof Error,
    message: failures[0]?.message,
    hasCause: Object.hasOwn(failures[0] ?? {}, 'cause'),
    cause: failures[0]?.cause,
  }).toEqual({
    outcome: {rejected: undefined},
    count: 1,
    isError: true,
    message: 'undefined',
    hasCause: true,
    cause: undefined,
  });
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.rejection.test.ts"
